def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def min_level_to_build_deck(n, k, cards):
    min_level = 1
    while True:
        valid_cards = [card for card in cards if card[2] <= min_level and not is_prime(card[1])]
        if sum(card[0] for card in valid_cards) >= k:
            return min_level
        min_level += 1
        if min_level > n:
            return -1

